        },
        {
          "as": "row",
          "expr": "datum.row0 - 1",
          "type": "formula"
        },
        {
          "expr": "datum.row < floor((height - 38) / 34)",
          "type": "filter"
        }
      ]
    },
    {
      "name": "head",
      "values": [
        {
          "align": "left",
          "key": "value",
          "label": "執行環境 (data.jt_runtime.label)",
