          "right": false,
          "x": 0
        },
        {
          "align": "right",
          "key": "alerts",
          "label": "告警",
          "num": true,
          "right": true,
          "x": 0
        }
      ]
    }
  ],
  "marks": [
    {
      "encode": {
        "update": {
          "align": {
            "field": "align"
          },
          "cursor": {
            "value": "pointer"
