          },
          "strokeWidth": {
            "value": 2
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "value": 38
          },
          "y2": {
            "value": 38
          }
        }
      },
      "type": "rule"
    },
    {
      "encode": {
        "hover": {
          "fill": {
            "value": "#F5F7FA"
          },
          "fillOpacity": {
            "value": 1
          }
        },
        "update": {
          "fill": {
            "value": "#FFFFFF"
          },
          "fillOpacity": {
            "value": 0
          },
          "height": {
            "value": 34
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "signal": "datum.row * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "rect"
    },
    {
      "encode": {
        "update": {
          "stroke": {
            "value": "#D3DAE6"
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "signal": "(datum.row + 1) * 34 + 38"
          },
          "y2": {
            "signal": "(datum.row + 1) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "rule"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "left"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#006BB4"
          },
          "limit": {
            "signal": "width - 90"
          },
          "text": {
            "field": "value"
          },
          "tooltip": {
            "signal": "'點擊以篩選' + ': ' + datum.value"
          },
          "x": {
            "value": 0
          },
          "y": {
            "signal": "(datum.row + 0.5) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "name": "jtCell_value",
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "right"
          },
          "text": {
            "signal": "format(datum.alerts, ',')"
          },
          "x": {
            "signal": "width - 0"
          },
          "y": {
            "signal": "(datum.row + 0.5) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "text"
    }
  ],
  "padding": {
